 "color": {
  "$type": "color",
  "$description": "意味の層。部品はこの層だけを参照する",
  "surface": {
   "page": {
    "$value": "{base.paper.100}",
    "$description": "頁の地"
   },
   "card": {
    "$value": "{base.paper.000}",
    "$description": "カード ・ 帯の地"
   },
   "line": {
    "$value": "{base.paper.400}",
    "$description": "区切りの線。飾りなので状態を伝えるのに使わない（1.4:1）"
   }
  },
  "text": {
   "primary": {
    "$value": "{base.ink.900}",
    "$description": "本文"
   },
   "secondary": {
    "$value": "{base.ink.600}",
    "$description": "補足 ・ id ・ 日時"
   }
  },
  "status": {
   "$description": "判定の結果。必ず記号と語と一緒に使う（色だけで伝えない）",
   "verified": {
    "$description": "✓ verified。rule を満たす",
    "fg": {
     "$value": "{base.green.800}"
    },
    "bg": {
     "$value": "{base.green.100}"
    },
    "border": {
     "$value": "{base.green.700}"
    }
   },
   "violated": {
    "$description": "✕ violated。rule に反する",
    "fg": {
     "$value": "{base.rose.700}"
    },
    "bg": {
     "$value": "{base.rose.100}"
    },
    "border": {
     "$value": "{base.rose.700}"
    }
   },
   "unverified": {
    "$description": "？ unverified。まだ判定していない、または rule の版が変わって判定が効かない",
    "fg": {
     "$value": "{base.amber.700}"
    },
    "bg": {
     "$value": "{base.amber.100}"
    },
    "border": {
     "$value": "{base.amber.700}"
    }
   }
  },
  "exception": {
   "$description": "意図に無い変更。まとめの例外の一覧の枠。violated と同じ色で、記号「！」と語「例外」を添える",
   "fg": {
    "$value": "{color.status.violated.fg}"
   },
   "bg": {
    "$value": "{color.status.violated.bg}"
   },
   "border": {
    "$value": "{color.status.violated.border}"
   }
  },
  "diff": {
   "$description": "変更前と変更後。状態の色（緑 ・ 赤）と混ぜないため、別の色相にし、列の題「変更前」「変更後」と記号「−」「＋」を必ず添える",
   "before": {
    "fg": {
     "$value": "{base.sand.700}"
    },
    "bg": {
     "$value": "{base.sand.100}"
    }
   },
   "after": {
    "fg": {
     "$value": "{base.teal.700}"
    },
    "bg": {
     "$value": "{base.teal.100}"
    }
   }
  },
  "judge": {
   "$description": "判定した者（機械 ・ AI ・ 人）。色で分けず、語で分ける。札の枠だけを持つ",
   "border": {
    "$value": "{base.ink.600}"
   },
   "fg": {
    "$value": "{base.ink.900}"
   }
  },
  "next": {
   "$description": "次にすることの帯。頁に1つだけ置く",
   "fg": {
    "$value": "{base.paper.000}"
   },
   "bg": {
    "$value": "{base.teal.700}"
   }
  },
  "focus": {
   "$value": "{base.teal.700}",
   "$description": "フォーカスの輪。2px 以上で描く"
  },
  "link": {
   "$value": "{base.teal.700}",
   "$description": "リンク。下線を付ける（色だけで見分けさせない）"
  }
 },
 "space": {
  "$type": "dimension",
  "gutter": {
   "$value": {
    "value": 16,
    "unit": "px"
   },
   "$description": "頁の左右の余白（幅 358px でも同じ）"
  },
  "stack": {
   "$value": {
    "value": 12,
    "unit": "px"
   },
   "$description": "カードどうしの間"
  }
 },
 "radius": {
  "$type": "dimension",
  "card": {
   "$value": {
    "value": 12,
    "unit": "px"
   }
  },
  "badge": {
   "$value": {
    "value": 6,
    "unit": "px"
   }
  }
 },
 "border": {
  "$type": "dimension",
  "state": {
   "$value": {
    "value": 2,
    "unit": "px"
   },
   "$description": "状態を持つ枠の太さ"
  },
  "focus": {
   "$value": {
    "value": 2,
    "unit": "px"
   }
  }
 },
 "font": {
  "body": {
   "$type": "fontFamily",
   "$value": [
    "Noto Sans JP",
    "Hiragino Kaku Gothic ProN",
    "system-ui",
    "sans-serif"
   ]
  },
  "mono": {
   "$type": "fontFamily",
   "$value": [
    "JetBrains Mono",
    "ui-monospace",
    "monospace"
   ],
   "$description": "id ・ 欄の経路 ・ コマンド ・ 値"
  }
 }
}
